CREATE TABLE `t_engine` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `code` varchar(64) DEFAULT NULL COMMENT 'Engine code (external API  use)',
  `name` varchar(64) DEFAULT NULL COMMENT 'Engine name',
  `description` varchar(500) DEFAULT NULL COMMENT 'Description',
  `status` int(11) DEFAULT '1' COMMENT '0 deleted 1 active',
  `created_time` datetime DEFAULT NULL,
  `updated_time` datetime DEFAULT NULL,
  `created_by` bigint(20) DEFAULT NULL,
  `organ_id` bigint(20) NOT NULL DEFAULT '0' COMMENT 'Owning organization: 0 platform-shared',
  PRIMARY KEY (`id`),
  KEY `idx_engine_code` (`code`),
  KEY `idx_engine_status` (`status`),
  KEY `idx_engine_organ` (`organ_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1510 DEFAULT CHARSET=utf8mb4 COMMENT='engine';
