--
-- Table structure for table `t_flow_publish`
--

DROP TABLE IF EXISTS `t_flow_publish`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `t_flow_publish` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `version_id` int(11) NOT NULL COMMENT 'Published version',
  `artifact` mediumtext NOT NULL COMMENT 'fully executable config snapshot JSON(node/ edge/Rule plan/Scorecard/ list)',
  `artifact_sha256` char(64) NOT NULL COMMENT 'Artifact digest: tamper-proof, easy diff between two publishes',
  `publish_seq` int(11) NOT NULL DEFAULT '1' COMMENT 'Publish sequence within the same version, incremental',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1 in effect / 0 superseded by a newer publish',
  `traffic_weight` int(11) NOT NULL DEFAULT '100' COMMENT 'Gray traffic weight 0-100; route by weight when multiple versions coexist',
  `shadow` tinyint(4) NOT NULL DEFAULT '0' COMMENT 'Shadow mode: 1 Evaluate and log only; no result returned, no traffic routing',
  `remark` varchar(500) DEFAULT NULL COMMENT 'Publish note (what changed and why)',
  `published_by` bigint(20) DEFAULT NULL COMMENT 'Publisher',
  `published_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Publish time',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Creation time',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Update time',
  `deleted` tinyint(4) NOT NULL DEFAULT '0' COMMENT 'Soft delete 0/1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_publish_version_seq` (`version_id`,`publish_seq`),
  KEY `idx_publish_status` (`status`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COMMENT='Decision flow publish artifact: immutable config snapshot solidified at publish';
/*!40101 SET character_set_client = @saved_cs_client */;

