--
-- Table structure for table `t_rule`
--

DROP TABLE IF EXISTS `t_rule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `t_rule` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `name` varchar(500) DEFAULT NULL,
  `code` varchar(500) DEFAULT NULL,
  `description` text COMMENT 'Rule description',
  `priority` int(4) DEFAULT NULL COMMENT 'Priority; smaller runs first',
  `parent_id` int(11) DEFAULT NULL COMMENT 'Parent node id(directory)',
  `created_by` bigint(20) DEFAULT NULL,
  `organ_id` bigint(20) NOT NULL DEFAULT '0' COMMENT 'Owning organization: 0 platform-shared',
  `engine_id` int(11) DEFAULT NULL COMMENT 'engine id',
  `status` int(2) DEFAULT '1' COMMENT '0 disabled 1 enabled -1 Delete',
  `deleted` tinyint(4) NOT NULL DEFAULT '0',
  `type` int(2) DEFAULT NULL COMMENT '0 system 1 organization 2 engine',
  `is_non` int(2) DEFAULT '0' COMMENT 'Negate the whole condition set 0 No 1 Yes',
  `content` longtext COMMENT 'Rule content',
  `definition` mediumtext COMMENT 'structured definitionJSON(source of truth, DRL generated from it)',
  `created_time` datetime DEFAULT NULL,
  `updated_time` datetime DEFAULT NULL,
  `rule_type` smallint(2) DEFAULT '0' COMMENT '0 Hard reject 1 score adjust',
  `rule_audit` smallint(2) DEFAULT NULL COMMENT 'Audit status',
  `score` int(11) DEFAULT NULL COMMENT 'Score of a score-adjust rule',
  `last_logical` varchar(50) DEFAULT NULL COMMENT 'Logical connector between conditions AND/OR',
  `result_type_v2` varchar(20) DEFAULT NULL COMMENT 'Strongly-typed result: PASS/DENY/MANUAL/ADD_SCORE/SUB_SCORE',
  `score_value` int(11) DEFAULT NULL COMMENT 'Score of a scoring result (positive adds, negative deducts)',
  `condition_version` tinyint(4) NOT NULL DEFAULT '1' COMMENT 'Condition storage version: 1 early definition / 2 AST  table',
  PRIMARY KEY (`id`),
  KEY `idx_rule_scope` (`engine_id`,`status`),
  KEY `idx_rule_code` (`code`),
  KEY `idx_rule_condition_version` (`condition_version`),
  KEY `idx_rule_organ` (`organ_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1547 DEFAULT CHARSET=utf8mb4 COMMENT='rule';
/*!40101 SET character_set_client = @saved_cs_client */;

