--
-- Table structure for table `t_rule_condition`
--

DROP TABLE IF EXISTS `t_rule_condition`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `t_rule_condition` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `rule_id` int(11) NOT NULL COMMENT 'Owning rule t_rule.id',
  `parent_id` bigint(20) DEFAULT NULL COMMENT 'Parent condition node id; NULL  denotes the root node',
  `node_type` tinyint(4) NOT NULL COMMENT 'Node type: 1 leaf / 2 AND  group / 3 OR  group / 4 NOT',
  `field_code` varchar(100) DEFAULT NULL COMMENT 'Leaf node: field code (e.g.  f_PBOC_AGE)',
  `operator` varchar(20) DEFAULT NULL COMMENT 'Leaf node: operator enum name (e.g.  GT / IN / CONTAINS)',
  `value` varchar(1000) DEFAULT NULL COMMENT 'Leaf node: comparison values; separate multiple values with commas',
  `sort_no` int(11) NOT NULL DEFAULT '0' COMMENT 'Order among sibling nodes',
  `depth` tinyint(4) NOT NULL DEFAULT '1' COMMENT 'Node depth, root is  1; depth-limited to prevent expression explosion',
  `remark` varchar(500) DEFAULT NULL COMMENT 'Remark',
  `created_by` bigint(20) DEFAULT NULL COMMENT 'Creator',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Creation time',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Update time',
  `deleted` tinyint(4) NOT NULL DEFAULT '0' COMMENT 'Soft delete: 0 not deleted / 1 deleted',
  PRIMARY KEY (`id`),
  KEY `idx_rule_condition_rule` (`rule_id`,`deleted`),
  KEY `idx_rule_condition_parent` (`parent_id`),
  KEY `idx_rule_condition_field` (`field_code`)
) ENGINE=InnoDB AUTO_INCREMENT=50060 DEFAULT CHARSET=utf8mb4 COMMENT='Rule conditions AST: tree-structured condition expressions';
/*!40101 SET character_set_client = @saved_cs_client */;

